 if t=='hoodie':return f'<path d="M171 100q35-34 76 0l30 37 60 52-30 52-24-20v109H137V221l-25 20-29-52 60-52Z" {common}/><path d="M174 116q35 45 72 0l-15 64h-43Z" fill="#ffffff7d"/><rect x="164" y="251" width="91" height="30" rx="12" fill="#ffffff48"/>'
 if t=='lamp':return f'<path d="M150 116h120l35 114H115Z" {common}/><path d="M210 231v84m-64 0h128" stroke="{c}" stroke-width="17" stroke-linecap="round"/><circle cx="210" cy="231" r="13" fill="#f0c76b"/>'
 if t=='diffuser':return f'<path d="M140 180h140l30 130H110Z" {common}/><path d="M177 149q-20-27 0-46m34 55q-21-37 0-67m31 66q-18-31 0-54" stroke="{c}" opacity=".65" stroke-width="8" stroke-linecap="round" fill="none"/><path d="M137 275h146" stroke="#fff" stroke-width="10" opacity=".7"/>'
 if t=='mug':return f'<rect x="128" y="115" width="160" height="210" rx="19" {common}/><path d="M287 145h25q40 0 40 40t-40 40h-25" fill="none" stroke="{c}" stroke-width="19"/><path d="M152 147h113" stroke="#fff" stroke-width="10" opacity=".5"/>'
 if t=='skincare':return f'<rect x="113" y="153" width="100" height="145" rx="18" {common}/><rect x="140" y="124" width="46" height="30" rx="5" fill="{c}"/><rect x="234" y="126" width="73" height="172" rx="12" fill="#fff" stroke="{c}" stroke-width="9"/><path d="M128 229h68m54-7h41" stroke="#fff" stroke-width="9"/>'
 if t=='serum':return f'<rect x="157" y="151" width="106" height="157" rx="17" {common}/><rect x="174" y="116" width="72" height="45" rx="10" fill="#303f59"/><path d="M210 118V91" stroke="#303f59" stroke-width="13" stroke-linecap="round"/><path d="M188 240h45" stroke="white" stroke-width="8"/>'
