(out/'fallback.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" width="420" height="400"><rect width="420" height="400" fill="#eceafb"/><text x="210" y="220" text-anchor="middle" font-size="68">🛍️</text></svg>')
